 487	fn print_messages(
 488	    store: &squad::store::Store,
 489	    messages: &[squad::store::MessageRecord],
 490	    receiver: Option<&str>,
 491	) -> Result<()> {
 492	    for msg in messages {
 493	        if msg.kind == "task_assigned" {
 494	            let task = msg
 495	                .task_id
 496	                .as_deref()
 497	                .and_then(|task_id| store.get_task(task_id).transpose())
 498	                .transpose()?;
 499	            println!(
 500	                "[task {}] queued from {}",
 501	                msg.task_id.as_deref().unwrap_or("unknown"),
 502	                msg.from_agent
 503	            );
 504	            println!("  Title: {}", msg.content);
 505	            if let Some(task) = task {
 506	                println!("  Body: {}", task.body);
 507	                println!(
 508	                    "  Assigned to: {}",
 509	                    task.assigned_to.unwrap_or_else(|| "unassigned".to_string())
 510	                );
 511	                println!("  Status: {}", task.status);
 512	            }
 513	            if let Some(id) = receiver {
 514	                if let Some(task_id) = &msg.task_id {
 515	                    println!(
 516	                        "  → Reply: squad send --task-id {task_id} {id} {} \"<your response>\"",
 517	                        msg.from_agent
 518	                    );
 519	                }
 520	            }
 521	        } else {
 522	            println!("[from {}] {}", msg.from_agent, msg.content);
 523	            if let Some(id) = receiver {
 524	                println!(
 525	                    "  → Reply: squad send {id} {} \"<your response>\"",
 526	                    msg.from_agent
 527	                );
 528	            }
 529	        }
 530	    }
 531	    if let Some(id) = receiver {
 532	        if !messages.is_empty() {
 533	            println!(
 534	                "  → After processing, run `squad receive {id} --wait` to continue listening."
 535	            );
 536	        }
 537	    }
 538	    Ok(())
 539	}
