 541	fn json_messages(
 542	    store: &squad::store::Store,
 543	    messages: Vec<squad::store::MessageRecord>,
 544	) -> Result<Vec<String>> {
 545	    let mut envelopes = Vec::with_capacity(messages.len());
 546	    for msg in messages {
 547	        let task = if msg.kind == "task_assigned" {
 548	            msg.task_id
 549	                .as_deref()
 550	                .and_then(|task_id| store.get_task(task_id).transpose())
 551	                .transpose()?
 552	        } else {
 553	            None
 554	        };
 555	        envelopes.push(ReceiveEnvelope {
 556	            id: msg.id,
 557	            from: msg.from_agent,
 558	            to: msg.to_agent,
 559	            content: msg.content,
 560	            created_at: msg.created_at,
 561	            read: msg.read,
 562	            kind: msg.kind,
 563	            task_id: msg.task_id,
 564	            reply_to: msg.reply_to,
 565	            task,
 566	        });
 567	    }
 568	    envelopes
 569	        .into_iter()
 570	        .map(|envelope| serde_json::to_string(&envelope).map_err(Into::into))
 571	        .collect()
 572	}
 573	
 574	fn print_json_messages(
 575	    store: &squad::store::Store,
 576	    messages: Vec<squad::store::MessageRecord>,
 577	) -> Result<()> {
 578	    for line in json_messages(store, messages)? {
 579	        println!("{line}");
 580	    }
 581	    Ok(())
 582	}
