 786	fn cmd_receive(agent: &str, wait: bool, timeout_secs: u64, json: bool) -> Result<()> {
 787	    let workspace = find_workspace()?;
 788	
 789	    // Validate session at entry (catches displacement immediately)
 790	    let store = open_store(&workspace)?;
 791	    ensure_agent_exists(&store, agent)?;
 792	    let session_token = store.get_session_token(agent)?;
 793	    check_session(&workspace, &store, agent)?;
 794	    store.touch_agent(agent)?;
 795	
 796	    if wait {
 797	        // Acquire exclusive file lock to prevent multiple concurrent receive --wait
 798	        // processes from competing for the same agent's messages.
 799	        let lock_dir = workspace.join("locks");
 800	        std::fs::create_dir_all(&lock_dir)?;
 801	        let lock_path = lock_dir.join(format!("{}.receive.lock", agent));
 802	        let lock_file = std::fs::File::create(&lock_path)
 803	            .with_context(|| format!("failed to create lock file: {}", lock_path.display()))?;
 804	        if lock_file.try_lock_exclusive().is_err() {
 805	            bail!(
 806	                "Another `squad receive --wait` is already running for agent '{}'. \
 807	                 Only one receive --wait per agent is allowed. Use `squad receive {}` \
 808	                 (without --wait) for non-blocking polling.",
 809	                agent,
 810	                agent
 811	            );
 812	        }
 813	        // Keep _lock_file alive for the duration of the wait loop (lock released on drop).
 814	        let _lock_guard = lock_file;
 815	
 816	        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(timeout_secs);
 817	        let mut last_heartbeat = std::time::Instant::now();
 818	        loop {
 819	            let store = open_store(&workspace)?;
 820	
 821	            // Re-check for displacement on each poll (~500ms)
 822	            check_session_token(&workspace, &store, agent, session_token.as_deref())?;
 823	
 824	            // Heartbeat: update last_seen every 30s so other agents know we're alive
 825	            if last_heartbeat.elapsed() >= std::time::Duration::from_secs(30) {
 826	                store.touch_agent(agent)?;
 827	                last_heartbeat = std::time::Instant::now();
 828	            }
 829	
 830	            if store.has_unread_messages(agent)? {
 831	                let messages = store.receive_messages(agent)?;
 832	                if !messages.is_empty() {
 833	                    if json {
 834	                        print_json_messages(&store, messages)?;
 835	                    } else {
 836	                        print_messages(&store, &messages, Some(agent))?;
 837	                    }
 838	                    return Ok(());
 839	                }
 840	            }
 841	            if std::time::Instant::now() > deadline {
 842	                if json {
 843	                    return Ok(());
 844	                } else {
 845	                    println!(
 846	                        "No new messages (timed out after {timeout_secs}s). Run `squad receive {agent} --wait` to continue listening."
 847	                    );
 848	                }
 849	                return Ok(());
 850	            }
 851	            std::thread::sleep(std::time::Duration::from_millis(500));
 852	        }
 853	    } else {
 854	        let messages = store.receive_messages(agent)?;
 855	        if messages.is_empty() {
 856	            if json {
 857	                return Ok(());
 858	            } else {
 859	                println!("No new messages. Run `squad receive {agent} --wait` to keep listening.");
 860	            }
 861	        } else {
 862	            if json {
 863	                print_json_messages(&store, messages)?;
 864	            } else {
 865	                print_messages(&store, &messages, Some(agent))?;
 866	            }
 867	        }
 868	        Ok(())
 869	    }
 870	}
