 883	            if args.len() != 3 {
 884	                bail!("Usage: squad task ack <agent> <task-id>");
 885	            }
 886	            cmd_task_ack(&args[1], &args[2])
 887	        }
 888	        "complete" => {
 889	            if args.len() < 5 {
 890	                bail!("Usage: squad task complete <agent> <task-id> --summary <text>");
 891	            }
 892	            let summary = parse_task_complete_args(&args[1..])?;
 893	            cmd_task_complete(&args[1], &args[2], &summary)
 894	        }
 895	        "requeue" => {
 896	            if args.len() != 2 && args.len() != 4 {
 897	                bail!("Usage: squad task requeue <task-id> [--to <agent>]");
 898	            }
 899	            let assignee = match args.get(2).map(String::as_str) {
 900	                Some("--to") => Some(args.get(3).context("--to requires an agent id")?.as_str()),
 901	                Some(flag) => bail!("unknown task requeue flag: {flag}"),
 902	                None => None,
 903	            };
 904	            cmd_task_requeue(&args[1], assignee)
 905	        }
 906	        "list" => cmd_task_list(parse_task_list_args(&args[1..])?),
 907	        _ => bail!("Usage: squad task <create|ack|complete|requeue|list> ..."),
 908	    }
 909	}
