 45	    pub fn open(path: &Path) -> Result<Self> {
 46	        let conn = Connection::open(path)
 47	            .with_context(|| format!("failed to open database: {}", path.display()))?;
 48	        conn.execute_batch(
 49	            "PRAGMA journal_mode=WAL;
 50	             PRAGMA busy_timeout=5000;",
 51	        )?;
 52	        conn.execute_batch(
 53	            "CREATE TABLE IF NOT EXISTS agents (
 54	                id TEXT PRIMARY KEY,
 55	                role TEXT NOT NULL,
 56	                joined_at INTEGER NOT NULL,
 57	                session_token TEXT,
 58	                last_seen INTEGER,
 59	                status TEXT NOT NULL DEFAULT 'active',
 60	                archived_at INTEGER,
 61	                client_type TEXT,
 62	                protocol_version INTEGER
 63	             );
 64	             CREATE TABLE IF NOT EXISTS messages (
 65	                  id INTEGER PRIMARY KEY AUTOINCREMENT,
 66	                  from_agent TEXT NOT NULL,
 67	                 to_agent TEXT NOT NULL,
 68	                 content TEXT NOT NULL,
 69	                 created_at INTEGER NOT NULL,
 70	                 read INTEGER NOT NULL DEFAULT 0
 71	             );
 72	             CREATE TABLE IF NOT EXISTS tasks (
 73	                 id TEXT PRIMARY KEY,
 74	                 title TEXT NOT NULL,
 75	                 body TEXT NOT NULL,
 76	                 created_by TEXT NOT NULL,
 77	                 assigned_to TEXT,
 78	                 status TEXT NOT NULL,
 79	                 lease_owner TEXT,
 80	                 lease_expires_at INTEGER,
 81	                 result_summary TEXT,
 82	                 created_at INTEGER NOT NULL,
 83	                 updated_at INTEGER NOT NULL,
 84	                 completed_at INTEGER
 85	             );",
 86	        )?;
 87	        // Migrations: add columns if missing (existing DBs)
 88	        let _ = conn.execute_batch("ALTER TABLE agents ADD COLUMN session_token TEXT;");
 89	        let _ = conn.execute_batch("ALTER TABLE agents ADD COLUMN last_seen INTEGER;");
 90	        let _ = conn
 91	            .execute_batch("ALTER TABLE agents ADD COLUMN status TEXT NOT NULL DEFAULT 'active';");
 92	        let _ = conn.execute_batch("ALTER TABLE agents ADD COLUMN archived_at INTEGER;");
 93	        let _ = conn.execute_batch("ALTER TABLE agents ADD COLUMN client_type TEXT;");
 94	        let _ = conn.execute_batch("ALTER TABLE agents ADD COLUMN protocol_version INTEGER;");
 95	        let _ = conn
 96	            .execute_batch("ALTER TABLE messages ADD COLUMN kind TEXT NOT NULL DEFAULT 'note';");
 97	        let _ = conn.execute_batch("ALTER TABLE messages ADD COLUMN task_id TEXT;");
 98	        let _ = conn.execute_batch("ALTER TABLE messages ADD COLUMN reply_to INTEGER;");
 99	        let _ = conn.execute(
100	            "UPDATE agents SET status = 'active' WHERE status IS NULL OR status = ''",
101	            [],
102	        );
103	        let _ = conn.execute(
104	            "UPDATE messages SET kind = ?1 WHERE kind IS NULL OR kind = ''",
105	            [DEFAULT_MESSAGE_KIND],
106	        );
107	        Ok(Self { conn })
108	    }
