329	    /// Broadcast a message to all agents except the sender.
330	    pub fn broadcast_message(&self, from: &str, content: &str) -> Result<Vec<String>> {
331	        let agents = self.agent_names()?;
332	        let recipients: Vec<_> = agents.into_iter().filter(|a| a != from).collect();
333	        for to in &recipients {
