452	    pub fn create_task(
453	        &self,
454	        created_by: &str,
455	        assigned_to: &str,
456	        title: &str,
457	        body: &str,
458	    ) -> Result<String> {
459	        let now = chrono::Utc::now().timestamp();
460	        let task_id = uuid::Uuid::new_v4().to_string();
461	        let tx = self.conn.unchecked_transaction()?;
462	        let inserted = tx.execute(
463	            "INSERT INTO tasks (
464	                 id, title, body, created_by, assigned_to, status,
465	                 lease_owner, lease_expires_at, result_summary,
466	                 created_at, updated_at, completed_at
467	             )
468	             SELECT ?1, ?2, ?3, creator.id, assignee.id, ?4,
469	                    NULL, NULL, NULL, ?5, ?5, NULL
470	             FROM agents AS creator
471	             JOIN agents AS assignee
472	               ON assignee.id = ?7
473	              AND assignee.status = 'active'
474	             WHERE creator.id = ?6
475	               AND creator.status = 'active'",
476	            params![
477	                task_id,
478	                title,
479	                body,
480	                TASK_STATUS_QUEUED,
481	                now,
482	                created_by,
483	                assigned_to,
484	            ],
485	        )?;
486	        if inserted != 1 {
487	            let created_by_status: Option<String> = tx
488	                .query_row(
489	                    "SELECT status FROM agents WHERE id = ?1",
490	                    [created_by],
491	                    |row| row.get(0),
492	                )
493	                .optional()?;
494	            match created_by_status.as_deref() {
495	                Some("active") => {}
496	                Some("archived") => {
497	                    anyhow::bail!(
498	                        "{created_by} is archived. Re-join with `squad join {created_by}` to reactivate it."
499	                    )
500	                }
501	                Some(_) | None => {
502	                    let names = self.agent_names()?;
503	                    anyhow::bail!(
504	                        "{created_by} does not exist. Online agents: {}",
505	                        names.join(", ")
506	                    )
507	                }
508	            }
509	
510	            let assigned_to_status: Option<String> = tx
511	                .query_row(
512	                    "SELECT status FROM agents WHERE id = ?1",
513	                    [assigned_to],
514	                    |row| row.get(0),
515	                )
516	                .optional()?;
517	            match assigned_to_status.as_deref() {
518	                Some("active") => anyhow::bail!("failed to create task for {assigned_to}"),
519	                Some("archived") => {
520	                    anyhow::bail!(
521	                        "{assigned_to} is archived. Re-join with `squad join {assigned_to}` to reactivate it."
522	                    )
523	                }
524	                Some(_) | None => {
525	                    let names = self.agent_names()?;
526	                    anyhow::bail!(
527	                        "{assigned_to} does not exist. Online agents: {}",
528	                        names.join(", ")
529	                    )
530	                }
531	            }
532	        }
533	        tx.execute(
534	            "INSERT INTO messages (from_agent, to_agent, content, created_at, read, kind, task_id, reply_to)
535	             VALUES (?1, ?2, ?3, ?4, 0, ?5, ?6, NULL)",
536	            params![
537	                created_by,
538	                assigned_to,
539	                title,
540	                now,
541	                TASK_ASSIGNED_KIND,
542	                task_id.as_str(),
543	            ],
544	        )?;
545	        tx.commit()?;
546	        Ok(task_id)
547	    }
