624	    pub fn ack_task(&self, agent_id: &str, task_id: &str) -> Result<()> {
625	        self.require_active_agent(agent_id)?;
626	        let task = self.require_task(task_id)?;
627	        if task.status != TASK_STATUS_QUEUED {
628	            anyhow::bail!("task {task_id} is not queued");
629	        }
630	        if task.assigned_to.as_deref() != Some(agent_id) {
631	            anyhow::bail!("task {task_id} is not assigned to {agent_id}");
632	        }
633	
634	        let now = chrono::Utc::now().timestamp();
635	        let lease_expires_at = now + TASK_LEASE_SECS;
636	        let updated = self.conn.execute(
637	            "UPDATE tasks
638	             SET status = ?1, lease_owner = ?2, lease_expires_at = ?3, updated_at = ?4
639	             WHERE id = ?5 AND status = ?6 AND assigned_to = ?2",
640	            params![
641	                TASK_STATUS_ACKED,
642	                agent_id,
643	                lease_expires_at,
644	                now,
645	                task_id,
646	                TASK_STATUS_QUEUED,
647	            ],
648	        )?;
649	        ensure_task_updated(updated, task_id)?;
650	        Ok(())
651	    }
