726	    /// Return archived agents that still have pending tasks (queued or acked).
727	    /// Each entry is (agent_id, vec_of_task_ids), sorted by agent_id.
728	    pub fn archived_agents_with_pending_tasks(&self) -> Result<Vec<(String, Vec<String>)>> {
729	        let mut stmt = self.conn.prepare(
730	            "SELECT a.id, t.id
731	             FROM agents a
732	             JOIN tasks t ON (t.assigned_to = a.id OR t.lease_owner = a.id)
733	             WHERE a.status = 'archived'
734	               AND t.status IN ('queued', 'acked')
735	             ORDER BY a.id, t.rowid",
736	        )?;
737	        let rows = stmt
738	            .query_map([], |row| {
739	                Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
740	            })?
741	            .collect::<Result<Vec<_>, _>>()?;
742	
743	        let mut result: Vec<(String, Vec<String>)> = Vec::new();
744	        for (agent_id, task_id) in rows {
745	            if let Some(last) = result.last_mut() {
746	                if last.0 == agent_id {
747	                    last.1.push(task_id);
748	                    continue;
749	                }
750	            }
751	            result.push((agent_id, vec![task_id]));
752	        }
753	        Ok(result)
754	    }
