756	    /// Return active agents whose effective protocol version is below the threshold.
757	    /// Each entry is (agent_id, effective_version), sorted by agent_id.
758	    pub fn active_agents_below_protocol(
759	        &self,
760	        threshold: i64,
761	        default_version: i64,
762	    ) -> Result<Vec<(String, i64)>> {
763	        let mut stmt = self.conn.prepare(
764	            "SELECT id, protocol_version
765	             FROM agents
766	             WHERE status = 'active'
767	             ORDER BY id",
768	        )?;
769	        let rows = stmt
770	            .query_map([], |row| {
771	                let id: String = row.get(0)?;
772	                let pv: Option<i64> = row.get(1)?;
773	                Ok((id, pv))
774	            })?
775	            .collect::<Result<Vec<_>, _>>()?;
776	
777	        Ok(rows
778	            .into_iter()
779	            .filter_map(|(id, pv)| {
780	                let effective = pv.unwrap_or(default_version);
781	                if effective < threshold {
782	                    Some((id, effective))
783	                } else {
784	                    None
785	                }
786	            })
787	            .collect())
788	    }
789	}
