  4	/// Write a session token file for an agent.
  5	pub fn write_token(sessions_dir: &Path, agent_id: &str, token: &str) -> Result<()> {
  6	    std::fs::create_dir_all(sessions_dir)
  7	        .with_context(|| format!("failed to create {}", sessions_dir.display()))?;
  8	    let path = sessions_dir.join(agent_id);
  9	    std::fs::write(&path, token)
 10	        .with_context(|| format!("failed to write session file: {}", path.display()))?;
 11	    Ok(())
 12	}
 13	
 14	/// Read a session token file. Returns None if file does not exist.
 15	pub fn read_token(sessions_dir: &Path, agent_id: &str) -> Result<Option<String>> {
 16	    let path = sessions_dir.join(agent_id);
 17	    if !path.exists() {
 18	        return Ok(None);
 19	    }
 20	    let token = std::fs::read_to_string(&path)
 21	        .with_context(|| format!("failed to read session file: {}", path.display()))?;
 22	    Ok(Some(token))
 23	}
